insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l10-v1','Getting started at the gym','independent_check','targeted-listening-05/d2d37340e0427722a7946a7dbe83815d2bf5ab90410ef7229cf8156dfbdce75e/BH-TL05-L10_v1.mp3','d2d37340e0427722a7946a7dbe83815d2bf5ab90410ef7229cf8156dfbdce75e','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a conversation between a new gym member and a receptionist. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. This is a fresh check: listen once, without pausing, and answer on your own.','Rebuild the real order of the steps, even when the speakers mention them out of order.','[{"id": "q1", "prompt": "What must the member do immediately after paying?", "options": [{"value": "A", "label": "A  Book a fitness test."}, {"value": "B", "label": "B  Complete a health questionnaire."}, {"value": "C", "label": "C  Collect a membership card."}], "accepted_answers": ["B"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q2", "prompt": "When is the member''s photo taken?", "options": [{"value": "A", "label": "A  At the end of the fitness test."}, {"value": "B", "label": "B  When the questionnaire is handed in."}, {"value": "C", "label": "C  During the induction."}], "accepted_answers": ["A"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q3", "prompt": "What does the member need before booking an induction?", "options": [{"value": "A", "label": "A  A personal programme."}, {"value": "B", "label": "B  A trainer''s signature."}, {"value": "C", "label": "C  A membership card."}], "accepted_answers": ["C"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q4", "prompt": "What happens immediately after the induction?", "options": [{"value": "A", "label": "A  The card is printed."}, {"value": "B", "label": "B  The trainer writes a personal programme."}, {"value": "C", "label": "C  The member takes a fitness test."}], "accepted_answers": ["B"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q5", "prompt": "What is the final step before the member can train alone?", "options": [{"value": "A", "label": "A  Receiving a personal programme."}, {"value": "B", "label": "B  Booking a fitness test."}, {"value": "C", "label": "C  Swimming in the pool."}], "accepted_answers": ["A"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q6", "prompt": "From which point can the member use the pool?", "options": [{"value": "A", "label": "A  After the induction."}, {"value": "B", "label": "B  After the fitness test."}, {"value": "C", "label": "C  After completing the questionnaire."}], "accepted_answers": ["C"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening fresh check; not an official IELTS recording or a band assessment.", "focus": "Sequencing", "teacher_notes": "Transcript:\nMember: Hi. I''ve just joined the gym. What do I need to do before I can use the machines?\nReceptionist: Welcome! There are a few steps. You''ve already paid, so the next thing is a short health questionnaire. You fill that in here at reception.\nMember: And then I get my membership card?\nReceptionist: Not straight away. Once we have your questionnaire, you book a fitness test with a trainer. Your card is printed after the test, because it has your photo on it, and the trainer takes the photo at the end of the test.\nMember: OK. So when do I learn how to use the machines?\nReceptionist: That''s the induction session. You can only book it once you have your card, because the booking system asks for your card number.\nMember: And the induction is the final step?\nReceptionist: Nearly. After the induction, the trainer writes you a personal programme. When you''ve got that, you''re free to train on your own.\nMember: Can I use the swimming pool before all this?\nReceptionist: Yes, actually. The pool doesn''t need an induction, so you can swim as soon as your questionnaire is done.\n\nKey and teaching notes:\nq1: B. \"You''ve already paid, so the next thing is a short health questionnaire.\" Primary: Sequencing; supporting: Distractor resistance.\nq2: A. \"the trainer takes the photo at the end of the test\". Primary: Sequencing; supporting: Distractor resistance.\nq3: C. \"You can only book it once you have your card\". Primary: Sequencing; supporting: Distractor resistance.\nq4: B. \"After the induction, the trainer writes you a personal programme.\" Primary: Sequencing; supporting: Distractor resistance.\nq5: A. \"When you''ve got that, you''re free to train on your own.\" Primary: Sequencing; supporting: Distractor resistance.\nq6: C. \"you can swim as soon as your questionnaire is done\". Primary: Sequencing; supporting: Distractor resistance."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L10_v1.mp3", "sha256": "d2d37340e0427722a7946a7dbe83815d2bf5ab90410ef7229cf8156dfbdce75e"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "fb8badf0838872778c90d2d4ebc137106773aa818e77461cb1508b35815805b9", "voices": {"RECEPTIONIST": "Kylie", "MEMBER": "Frank"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L10_v1.mp3", "sha256": "d2d37340e0427722a7946a7dbe83815d2bf5ab90410ef7229cf8156dfbdce75e", "bytes": 3199980, "duration_seconds": 133.296, "integrated_lufs": -18.7, "true_peak_dbfs": -1.6, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.141, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'e1f5229c07fb5171374efe5a1e491b9bea725c2a7b773ad6c7e2091149d19c12') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l11-v1','Choosing next term''s modules','guided_practice','targeted-listening-05/73d108de1bd1053b87890c4ec31607bdfc3bf97f539562d91a22833dcf6868fe/BH-TL05-L11_v1.mp3','73d108de1bd1053b87890c4ec31607bdfc3bf97f539562d91a22833dcf6868fe','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a conversation between two students, Emma and Raj, about their course options. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. You may pause or replay for practice.','Listen for how each speaker feels, not only what they talk about. Words like "but", "honestly", "I''m not convinced" and "fair enough" often signal the real opinion.','[{"id": "q1", "prompt": "How does Raj feel about the Urban Planning lectures?", "options": [{"value": "A", "label": "A  They were inspiring."}, {"value": "B", "label": "B  They were too long."}, {"value": "C", "label": "C  They were hard to follow."}], "accepted_answers": ["A"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q2", "prompt": "What is Emma''s opinion of Statistics?", "options": [{"value": "A", "label": "A  It is too difficult."}, {"value": "B", "label": "B  It will help her find work."}, {"value": "C", "label": "C  It repeats what she studied at school."}], "accepted_answers": ["B"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q3", "prompt": "What is Raj''s attitude to Statistics?", "options": [{"value": "A", "label": "A  He is keen to start."}, {"value": "B", "label": "B  He thinks it is badly taught."}, {"value": "C", "label": "C  He doubts it will be useful to him."}], "accepted_answers": ["C"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q4", "prompt": "What is Raj''s condition for group work?", "options": [{"value": "A", "label": "A  Groups must be small."}, {"value": "B", "label": "B  Students must choose their own groups."}, {"value": "C", "label": "C  Tutors must check everyone''s work."}], "accepted_answers": ["B"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q5", "prompt": "What does Raj think about the cost of the Lisbon trip?", "options": [{"value": "A", "label": "A  It is acceptable."}, {"value": "B", "label": "B  It is too high."}, {"value": "C", "label": "C  It should be paid by the department."}], "accepted_answers": ["A"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q6", "prompt": "What is Raj''s view of Dr Moss?", "options": [{"value": "A", "label": "A  She does not know her subject well."}, {"value": "B", "label": "B  She speaks too quickly."}, {"value": "C", "label": "C  She sets too much work."}], "accepted_answers": ["B"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening practice; not an official IELTS recording or a band assessment.", "focus": "Speaker attitude or opinion", "teacher_notes": "Transcript:\nEmma: Have you decided which options to take next term, Raj?\nRaj: Almost. I''m definitely doing Urban Planning. The lectures last year were brilliant. I came out of every one full of ideas.\nEmma: I liked them too, though I found the reading list far too long.\nRaj: Fair enough. What about Statistics? It''s optional.\nEmma: I know people complain about it, but honestly, I think it''s worth doing. Employers keep asking for data skills.\nRaj: Hmm. I''m not convinced. I can''t see myself ever using it in the kind of job I want.\nEmma: And the group project? I''m a bit nervous. Last time, two people in my group did nothing.\nRaj: I don''t mind group work, as long as we choose our own groups. That''s the part I''d insist on.\nEmma: Then there''s the field trip to Lisbon. It sounds amazing, but it''s so expensive.\nRaj: Is it, though? Flights are cheap in March, and the department pays for the hostel. I think it''s reasonable.\nEmma: Maybe. And what did you think of the new tutor, Dr Moss?\nRaj: She clearly knows her subject, but she spoke so fast I couldn''t take notes. I hope she slows down.\n\nKey and teaching notes:\nq1: A. \"brilliant ... came out of every one full of ideas\" = inspiring. \"too long\" was Emma''s view of the reading list. Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq2: B. \"worth doing. Employers keep asking for data skills.\" She mentions others'' complaints but disagrees. Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq3: C. \"I''m not convinced. I can''t see myself ever using it\". Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq4: B. \"as long as we choose our own groups ... I''d insist on\". Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq5: A. \"Is it, though? ... I think it''s reasonable.\" Emma thinks it is expensive. Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq6: B. \"She clearly knows her subject, but she spoke so fast\". Primary: Speaker attitude or opinion; supporting: Paraphrase recognition."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L11_v1.mp3", "sha256": "73d108de1bd1053b87890c4ec31607bdfc3bf97f539562d91a22833dcf6868fe"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "131a3293ff8c61b39134b178fbbe8eaa2cf768c0a2f5aee9a975ec3d095dbe99", "voices": {"EMMA": "Katie", "RAJ": "Arjun"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L11_v1.mp3", "sha256": "73d108de1bd1053b87890c4ec31607bdfc3bf97f539562d91a22833dcf6868fe", "bytes": 3421739, "duration_seconds": 142.536, "integrated_lufs": -18.4, "true_peak_dbfs": -1.6, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.151, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'897e6d1edb1f48a4ea3b15e8899df8a9062c7b30f2cb2ae9f928ca03260aaead') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l12-v1','Looking back on the town festival','independent_check','targeted-listening-05/a3fdf6d974ac5281f449b4fa15e1f5e3f3d771281e60da3b5cf4c60e0dfaf2f0/BH-TL05-L12_v1.mp3','a3fdf6d974ac5281f449b4fa15e1f5e3f3d771281e60da3b5cf4c60e0dfaf2f0','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a conversation between two volunteers, Lucy and Peter, after a town festival. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. This is a fresh check: listen once, without pausing, and answer on your own.','Identify what Peter really thinks, even when Lucy offers a different view.','[{"id": "q1", "prompt": "What is Peter''s overall view of the festival?", "options": [{"value": "A", "label": "A  It went well."}, {"value": "B", "label": "B  It was disappointing."}, {"value": "C", "label": "C  It was too crowded."}], "accepted_answers": ["A"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q2", "prompt": "How does Peter feel about the new location?", "options": [{"value": "A", "label": "A  It was ideal."}, {"value": "B", "label": "B  It was hard to reach."}, {"value": "C", "label": "C  It was too small."}], "accepted_answers": ["B"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q3", "prompt": "What does Peter think of the local bands?", "options": [{"value": "A", "label": "A  They played for too long."}, {"value": "B", "label": "B  They were less popular than the famous singer."}, {"value": "C", "label": "C  They were better than the well-known performer."}], "accepted_answers": ["C"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q4", "prompt": "What does Peter think should be changed first?", "options": [{"value": "A", "label": "A  The number of food stalls."}, {"value": "B", "label": "B  The ticket prices."}, {"value": "C", "label": "C  The opening times."}], "accepted_answers": ["A"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q5", "prompt": "How did Peter feel about the weather before the festival?", "options": [{"value": "A", "label": "A  Anxious."}, {"value": "B", "label": "B  Unconcerned."}, {"value": "C", "label": "C  Annoyed."}], "accepted_answers": ["B"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q6", "prompt": "What is Peter''s opinion of the volunteers?", "options": [{"value": "A", "label": "A  They needed more training."}, {"value": "B", "label": "B  They did an excellent job."}, {"value": "C", "label": "C  They were often late."}], "accepted_answers": ["B"], "taxonomy_node_id": "0c24d56c-a8ad-4747-8fab-0a99042e6d77", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening fresh check; not an official IELTS recording or a band assessment.", "focus": "Speaker attitude or opinion", "teacher_notes": "Transcript:\nLucy: So, the festival''s over. What did you make of it, Peter?\nPeter: Overall, I''d call it a success. Far more people came than last year.\nLucy: And the new spot by the river was lovely, wasn''t it?\nPeter: It looked nice, but I wasn''t happy with it. It was a long walk from the bus station, and older visitors really struggled.\nLucy: True. What about the music? I thought the local bands were the best part.\nPeter: I''d agree with you there. To be honest, they were better than the famous singer we paid so much for.\nLucy: And the food stalls?\nPeter: There weren''t nearly enough. People were queuing for forty minutes. That''s the first thing I''d change.\nLucy: I was so worried the weather would ruin everything.\nPeter: I wasn''t. The forecast was good all week, and we had the big tents anyway.\nLucy: And the volunteers? Some were completely new.\nPeter: They were fantastic. Several had never done anything like it, but they stayed calm and friendly all weekend. I''d happily work with them again.\n\nKey and teaching notes:\nq1: A. \"I''d call it a success.\" Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq2: B. \"It looked nice, but I wasn''t happy ... a long walk from the bus station\". Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq3: C. \"they were better than the famous singer\". Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq4: A. \"There weren''t nearly enough ... That''s the first thing I''d change.\" Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq5: B. Lucy was worried; Peter: \"I wasn''t.\" Primary: Speaker attitude or opinion; supporting: Paraphrase recognition.\nq6: B. \"They were fantastic ... I''d happily work with them again.\" Primary: Speaker attitude or opinion; supporting: Paraphrase recognition."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L12_v1.mp3", "sha256": "a3fdf6d974ac5281f449b4fa15e1f5e3f3d771281e60da3b5cf4c60e0dfaf2f0"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "c41aa7abbc76720538fe7ac19aa16a283120a81df5ad9756e3448b65a1b896aa", "voices": {"LUCY": "Maggie", "PETER": "Vincent"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L12_v1.mp3", "sha256": "a3fdf6d974ac5281f449b4fa15e1f5e3f3d771281e60da3b5cf4c60e0dfaf2f0", "bytes": 3123955, "duration_seconds": 130.128, "integrated_lufs": -18.6, "true_peak_dbfs": -1.6, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.147, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'635e8519063d9736fbfd1b87f24812645b146634f9fd5ef7b3896578080e82c3') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l13-v1','A guided tour of Hartwell House','guided_practice','targeted-listening-05/fd0b1c23512a453050f30e412756a7efcb2aab58fe4dce23131b8180ddec3197/BH-TL05-L13_v1.mp3','fd0b1c23512a453050f30e412756a7efcb2aab58fe4dce23131b8180ddec3197','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a talk by a guide at the start of a tour of an old house. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. You may pause or replay for practice.','Ask WHY the speaker says something: to explain a rule, correct a mistake, warn, give a reason or set a task. The topic alone is not the purpose.','[{"id": "q1", "prompt": "Why does the guide mention camera flashes?", "options": [{"value": "A", "label": "A  To explain the reason for a rule."}, {"value": "B", "label": "B  To recommend a type of camera."}, {"value": "C", "label": "C  To describe a recent accident."}], "accepted_answers": ["A"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q2", "prompt": "Why does the guide mention the television drama?", "options": [{"value": "A", "label": "A  To advertise the programme."}, {"value": "B", "label": "B  To correct a possible misunderstanding."}, {"value": "C", "label": "C  To explain why the house is famous."}], "accepted_answers": ["B"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q3", "prompt": "Why are tea plants shown in the dining room?", "options": [{"value": "A", "label": "A  To remind servants of their work."}, {"value": "B", "label": "B  To decorate a plain room cheaply."}, {"value": "C", "label": "C  To show where the owner''s money came from."}], "accepted_answers": ["C"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q4", "prompt": "Why does the guide talk about the library windows?", "options": [{"value": "A", "label": "A  To warn visitors about bright light."}, {"value": "B", "label": "B  To explain a design decision."}, {"value": "C", "label": "C  To point out a building fault."}], "accepted_answers": ["B"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q5", "prompt": "Why does the guide mention the distance between the kitchen and the dining room?", "options": [{"value": "A", "label": "A  To give visitors a question to think about."}, {"value": "B", "label": "B  To apologise for a long walk."}, {"value": "C", "label": "C  To describe a fire."}], "accepted_answers": ["A"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q6", "prompt": "Why does the guide mention when the café closes?", "options": [{"value": "A", "label": "A  To recommend the food."}, {"value": "B", "label": "B  To suggest visitors eat before the tour."}, {"value": "C", "label": "C  To stop visitors being surprised later."}], "accepted_answers": ["C"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening practice; not an official IELTS recording or a band assessment.", "focus": "Speaker purpose", "teacher_notes": "Transcript:\nGuide: Good morning, and welcome to Hartwell House. Before we go in, I should mention that flash photography isn''t allowed inside, because camera flashes damage the old paintings. You''re welcome to take pictures in the gardens, though.\nGuide: Now, many of you will have seen the house in a television drama last year. I mention that because visitors often ask to see the famous staircase. In fact, that scene was filmed in a studio, not here, so please don''t go looking for it.\nGuide: The house was built in 1720 by a merchant called Thomas Hartwell, who made his money trading tea. That''s why almost every decoration in the dining room shows tea plants. He wanted his guests to know exactly where his wealth came from.\nGuide: Our first stop is the library. You''ll notice the windows face north. That wasn''t an accident. Hartwell''s daughter, who collected books, insisted on it, because direct sunlight fades the covers.\nGuide: After the library, we''ll see the kitchen. It''s a very long way from the dining room. I''d like you to think about why, and we''ll discuss your ideas at the end of the tour.\nGuide: Finally, a practical point. The tour lasts about an hour, and there''s a café by the gate. I''m telling you now because it closes at four, earlier than the house, and people are sometimes caught out.\n\nKey and teaching notes:\nq1: A. Flashes damage paintings, so flash photography is not allowed inside. Primary: Speaker purpose; supporting: Paraphrase recognition.\nq2: B. Visitors look for the staircase, but \"that scene was filmed in a studio\". Primary: Speaker purpose; supporting: Paraphrase recognition.\nq3: C. \"He wanted his guests to know exactly where his wealth came from.\" Primary: Speaker purpose; supporting: Paraphrase recognition.\nq4: B. \"That wasn''t an accident ... she insisted on it, because direct sunlight fades the covers.\" Primary: Speaker purpose; supporting: Paraphrase recognition.\nq5: A. \"I''d like you to think about why, and we''ll discuss your ideas\". Primary: Speaker purpose; supporting: Paraphrase recognition.\nq6: C. \"it closes at four ... people are sometimes caught out.\" Primary: Speaker purpose; supporting: Paraphrase recognition."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L13_v1.mp3", "sha256": "fd0b1c23512a453050f30e412756a7efcb2aab58fe4dce23131b8180ddec3197"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "ea29fc011fb86739d9c3026a27186df9868c09868bf174ba1eed7f524c852b6b", "voices": {"GUIDE": "Benjamin"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L13_v1.mp3", "sha256": "fd0b1c23512a453050f30e412756a7efcb2aab58fe4dce23131b8180ddec3197", "bytes": 3660206, "duration_seconds": 152.472, "integrated_lufs": -18.3, "true_peak_dbfs": -1.7, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.145, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'5a21de843fac7b2f5e0ec13687bffe5f17bc6f07c9e67cd5c66a6d4d0d6c58f5') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l14-v1','Welcome talk: Student Services','independent_check','targeted-listening-05/a312eaa1e1829c539c7da116796228835a38ead93193b9e89fc28c3c5b7dcac3/BH-TL05-L14_v1.mp3','a312eaa1e1829c539c7da116796228835a38ead93193b9e89fc28c3c5b7dcac3','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a welcome talk for new university students by Claire from Student Services. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. This is a fresh check: listen once, without pausing, and answer on your own.','For each point, decide why the speaker includes it.','[{"id": "q1", "prompt": "Why does Claire mention the email about societies?", "options": [{"value": "A", "label": "A  To make sure students read important information in it."}, {"value": "B", "label": "B  To persuade students to join a society."}, {"value": "C", "label": "C  To apologise for sending too many emails."}], "accepted_answers": ["A"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q2", "prompt": "Why does Claire talk about last year''s first-years?", "options": [{"value": "A", "label": "A  To praise their results."}, {"value": "B", "label": "B  To encourage new students to ask for help early."}, {"value": "C", "label": "C  To explain a change in the rules."}], "accepted_answers": ["B"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q3", "prompt": "Why does Claire mention the builders?", "options": [{"value": "A", "label": "A  To apologise for the noise."}, {"value": "B", "label": "B  To describe a new sports hall."}, {"value": "C", "label": "C  To tell students where to leave bicycles for now."}], "accepted_answers": ["C"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q4", "prompt": "Why does Claire mention second-year students?", "options": [{"value": "A", "label": "A  To suggest a cheaper way to get books."}, {"value": "B", "label": "B  To explain who organises the tour."}, {"value": "C", "label": "C  To warn about old editions."}], "accepted_answers": ["A"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q5", "prompt": "Why does Claire introduce Amir?", "options": [{"value": "A", "label": "A  He will give the next talk."}, {"value": "B", "label": "B  He will lead the campus tour."}, {"value": "C", "label": "C  He organises the book fair."}], "accepted_answers": ["B"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}, {"id": "q6", "prompt": "Why does Claire mention how long she has been talking?", "options": [{"value": "A", "label": "A  To apologise for running late."}, {"value": "B", "label": "B  To announce a break."}, {"value": "C", "label": "C  To invite questions."}], "accepted_answers": ["B"], "taxonomy_node_id": "896804e2-f2eb-4c92-80f3-4479e71c377b", "supporting_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening fresh check; not an official IELTS recording or a band assessment.", "focus": "Speaker purpose", "teacher_notes": "Transcript:\nClaire: Hello, everyone, and welcome to your first week. I''m Claire from Student Services, and I''ll keep this short.\nClaire: First, you''ll all have received an email with a long list of societies. I''m mentioning it because a lot of new students delete it, thinking it''s advertising. It actually contains the link to your timetable, so please do open it.\nClaire: Second, I want to tell you about last year''s first-years. Many of them waited until they were really struggling before they came to us. Please don''t do that. Come and see us early, even if a problem seems small.\nClaire: You may have noticed builders near the main gate. That''s a new bike park, and it won''t be finished until December. Until then, please lock your bicycles behind the sports hall, or they may be removed.\nClaire: Some of you have asked whether you need to buy every book on your reading lists. You don''t. Second-year students sell their old copies at the book fair in week two, usually for half price.\nClaire: Now, I''d like to introduce Amir, who''s sitting at the front. He''s in his final year, and he''ll be showing you around the campus after this.\nClaire: I''ve been talking for ten minutes, and I know you''ve had a long day, so let''s have a short break before the tour begins.\n\nKey and teaching notes:\nq1: A. \"It actually contains the link to your timetable, so please do open it.\" Primary: Speaker purpose; supporting: Paraphrase recognition.\nq2: B. \"Please don''t do that. Come and see us early\". Primary: Speaker purpose; supporting: Paraphrase recognition.\nq3: C. \"Until then, please lock your bicycles behind the sports hall\". Primary: Speaker purpose; supporting: Paraphrase recognition.\nq4: A. \"sell their old copies ... usually for half price.\" Primary: Speaker purpose; supporting: Paraphrase recognition.\nq5: B. \"he''ll be showing you around the campus after this.\" Primary: Speaker purpose; supporting: Paraphrase recognition.\nq6: B. \"so let''s have a short break\". Primary: Speaker purpose; supporting: Paraphrase recognition."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L14_v1.mp3", "sha256": "a312eaa1e1829c539c7da116796228835a38ead93193b9e89fc28c3c5b7dcac3"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "62a4c2d39ecf28605e1172616677c45518d74ac9710f6c378b1f87f200d79c9c", "voices": {"CLAIRE": "Marlene"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L14_v1.mp3", "sha256": "a312eaa1e1829c539c7da116796228835a38ead93193b9e89fc28c3c5b7dcac3", "bytes": 3664240, "duration_seconds": 152.64, "integrated_lufs": -18.3, "true_peak_dbfs": -1.6, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.149, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'2e78905d8d1fc7774c245686f36259dd1f18e3a4a43bcdb213c209f984b5629e') on conflict (code) do nothing;
